export interface DoudianImageTextPublishParams {
  mode: "cart" | "plain" // 图文类型。cart=挂车图文（带小黄车商品，有每日条数上限，实测默认 10 条/天）；plain=非挂车图文（不限条数，可另配「承接商品」）。这是抖店创作弹层顶部那两张卡片。
  commit: "dry-run" | "publish" // 落点。dry-run=把表单按入参填满、跑完自检就停（不可逆动作一步都不做）；publish=真的按下「发布」。发布后内容立即公开，挂车还会消耗当天一条配额。
  productId?: string // 小黄车商品 ID（抖店商品 ID）。mode=cart 时必传；plain 时忽略。按「商品编号」精确检索，搜不到会明确区分「确实没这个商品/不支持挂车」与「选择器坏了」。
  images?: { type: "image"; url?: string; localPath?: string; filename?: string; mimeType?: string }[] // 图片（最多 35 张，第 1 张是封面）。每项给 url 或 localPath 二选一。不传时：挂车模式会去用「已选商品已有素材图片，一键添加」；非挂车模式没有素材可用，会直接失败。
  copy?: "ai" | "manual" // 文案来源。ai=用抖店自己生成的标题与正文（挂车选完商品后它会自动写一版，可能失败，失败时本 book 会在自检处停下）；manual=用入参的 title/body 覆盖。选 manual 就必须同时给 title 和 body；选 ai 时不要传 body（会被判为自相矛盾并失败，而不是把两份文案拼在一起）。
  title?: string // 图文标题。不传则保留抖店 AI 生成的那条。
  body?: string // 正文（含话题标签，上限 1000 字，抖店提示带电商热点话题最高有 10% 流量扶持）。仅在 copy=manual 时生效。 ⚠️ 正文里【禁止出现 #】：抖音话题是编辑器实体，必须在正文里敲 # 后从弹出候选里选中才会生成，而本步用的是 paste，paste 进去的 #xxx 永远是纯文本——发布后点不开、也拿不到抖店说的「点话题，最高享 10%流量扶持」。2026-09-21 实测 Enter / ArrowDown+Enter / 点击候选行三种方式均无法用合成事件选中，所以本 book 造不出话题实体，只能禁止。需要话题就发布后人工补，或改用 copy=ai（抖店自己生成的文案带真实体）。
  cartTitle?: string // 小黄车标题（挂车专有，上限 12 字）。不传则保留抖店 AI 生成的那条。
  music?: "auto" | "skip" // 配乐。auto=从「选择音乐」的推荐列表里取第一首；skip=不选（注意：它在表单里是带 * 的必填项，跳过大概率会在提交时被拦）。已经有音乐时两者都不动它。
  selfDeclaration?: "无需添加自主声明" | "内容由AI生成" | "内容为个人观点或见解" | "内容为转载信息" | "内容含营销推广信息" | "虚构演绎，仅供娱乐" // 作者自主声明（抖店弹层里的单选项，原文照抄）。默认与抖店默认值一致，此时本步 no-op。文案若由 AI 生成，按平台要求应选「内容由AI生成」。
  onQuotaExhausted?: "fail" | "fallback-plain" // mode=cart 但挂车不可用时（今日配额用尽，或该抖音号 canBind=false / 保证金未缴）的处置。fail=停下并报出实际的配额数字；fallback-plain=自动降级成非挂车继续（产出里的 mode 会是 plain，note 说明降级原因）。
}

